// ============================================================================
//  The host capability manifest (WIRE_FORMAT.md §27) and the corpus-family gate
//  (§27.7, Phase 1938).
//
//  The manifest is generated by scripts/host-capability.mjs; this test runs its
//  --check, so the gate and the CLI share one implementation. The family gate
//  derives the family set from the corpus tree and fails on a family the
//  manifest does not name, or one it names that the corpus no longer has.
// ============================================================================

import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import { wireCorpusRoot } from '../../../dev-scripts/corpus-root.mjs';
import { corpusFamilies, HOST_CORPUS_FAMILIES } from '../scripts/host-capability.mjs';

const here = dirname(fileURLToPath(import.meta.url));
const packageRoot = join(here, '..');
const script = join(packageRoot, 'scripts', 'host-capability.mjs');

describe('host capability manifest', () => {
  it('is what this host declares (re-run scripts/host-capability.mjs on mismatch)', () => {
    const result = spawnSync(process.execPath, [script, '--check'], {
      encoding: 'utf8',
      cwd: packageRoot,
    });
    const report = (result.stderr || result.stdout || '').trim();
    expect(result.status, `host-capability --check said:\n${report}`).toBe(0);
  });

  it('names every corpus family and no other', () => {
    // The corpus is the oracle: an absent one throws in the resolver or fails
    // the read below, never skips.
    const families = corpusFamilies(wireCorpusRoot());
    const declared = new Set(Object.keys(HOST_CORPUS_FAMILIES));
    const missing = [...families].filter((f) => !declared.has(f)).sort();
    const stale = [...declared].filter((f) => !families.has(f)).sort();
    expect(missing, 'corpus families this host does not name').toEqual([]);
    expect(stale, 'families this host names that the corpus no longer has').toEqual([]);
  });

  it('derives a self-enumerated family the printer could not see', () => {
    const dir = mkdtempSync(join(tmpdir(), 'fuaran-ts-families-'));
    try {
      const write = (rel: string, body: string) => {
        mkdirSync(dirname(join(dir, rel)), { recursive: true });
        writeFileSync(join(dir, rel), body);
      };
      write('manifest.json', '{"fixtures":[{"kind":"node-round-trip"}]}');
      write('newfamily/manifest.json', '{"cases":[]}');
      write('split/manifest.json', '{"families":[{"id":"a"},{"id":"b"}]}');
      write('goldens/goldens.json', '{}');
      expect([...corpusFamilies(dir)].sort()).toEqual([
        'newfamily',
        'node-round-trip',
        'split/a',
        'split/b',
      ]);
    } finally {
      rmSync(dir, { recursive: true, force: true });
    }
  });
});
